func TestAddressStructFields(t *testing.T) {
	a := Address{
		ID:          1,
		Username:    "alice",
		Domain:      "cloistr.xyz",
		Pubkey:      "abc",
		Active:      true,
		Verified:    true,
		IsPrimary:   true,
		NIP05Active: true,
	}
	if !a.IsPrimary {
		t.Error("IsPrimary not set")
	}
	if !a.NIP05Active {
		t.Error("NIP05Active not set")
	}
}

// TestAddressSummaryFields verifies AddressSummary has the expected fields.
func TestAddressSummaryFields(t *testing.T) {
	s := AddressSummary{
		Username:    "bob",
		Domain:      "cloistr.xyz",
		Active:      true,
		IsPrimary:   false,
		NIP05Active: true,
		CreatedAt:   time.Now(),
	}
	if s.Username != "bob" {
		t.Error("Username not set")
	}
	if s.IsPrimary {
		t.Error("IsPrimary should be false")
	}
}

// ---------------------------------------------------------------------------
// Primary-reassignment logic (table-driven, no DB)
// ---------------------------------------------------------------------------

// TestPrimaryReassignmentConditions documents when promotion should occur.
func TestPrimaryReassignmentConditions(t *testing.T) {
	type testCase struct {
		name         string
		wasPrimary   bool
		othersCount  int
		shouldPromote bool
	}

	cases := []testCase{
		{"was_primary_with_others", true, 2, true},
		{"was_primary_no_others", true, 0, false},
		{"not_primary_with_others", false, 2, false},
		{"not_primary_no_others", false, 0, false},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// The logic in AdminRevokeAddress:
			//   if wasPrimary && others > 0 { promote }
			shouldPromote := tc.wasPrimary && tc.othersCount > 0
			if shouldPromote != tc.shouldPromote {
				t.Errorf("expected shouldPromote=%v, got %v", tc.shouldPromote, shouldPromote)
			}
		})
	}
}

// TestAliasIsFirstLogic documents the is_primary/nip05_active assignment for new addresses.
func TestAliasIsFirstLogic(t *testing.T) {
	type testCase struct {
		name           string
		existingCount  int
		wantIsPrimary  bool
		wantNIP05Active bool
	}

	cases := []testCase{
		{"first_address", 0, true, true},
		{"second_address_alias", 1, false, false},
		{"third_address_alias", 5, false, false},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			isFirst := tc.existingCount == 0
			if isFirst != tc.wantIsPrimary {
				t.Errorf("is_primary: want %v got %v", tc.wantIsPrimary, isFirst)
			}
			if isFirst != tc.wantNIP05Active {
				t.Errorf("nip05_active: want %v got %v", tc.wantNIP05Active, isFirst)
			}
		})
	}
}
